import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { io } from 'socket.io-client';

const socket = io('http://localhost:5000');

const MessagesList = ({ currentUser, onSelectUser }) => {
  const [users, setUsers] = useState([]);

  useEffect(() => {
    if (currentUser) {
      socket.emit('user_connected', { userId: currentUser.id, name: currentUser.name });
    }

    socket.on('update_user_list', (updatedUsers) => {
      setUsers(updatedUsers.filter(u => u.userId !== currentUser.id));
    });

    return () => socket.disconnect();
  }, [currentUser]);

  return (
    <div className="users-list">
      {users.map(user => (
        <div 
          key={user.userId} 
          className={`user ${user.online ? 'online' : 'offline'}`}
          onClick={() => onSelectUser(user)}
        >
          {user.name} {user.online ? '(Online)' : '(Offline)'}
        </div>
      ))}
    </div>
  );
};

export default MessagesList;
